def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # The frame's width is the contiguous run of its color at the top edge.
    width = 0
    while width < w and grid[0][width] == frame:
        width += 1

    # Rows that span the full frame width are panel separators.
    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(width))
    ]

    # Collect each colored shape on the right, normalized to its bounding box.
    colors = {}
    for r in range(h):
        for c in range(width, w):
            value = grid[r][c]
            if value != 0 and value != frame:
                colors.setdefault(value, []).append((r, c))

    shapes = {}
    for color, cells in colors.items():
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        shapes[color] = (
            max_r - min_r + 1,
            max_c - min_c + 1,
            {(r - min_r, c - min_c) for r, c in cells},
        )

    out = [row[:width] for row in grid]

    for top, bottom in zip(separators, separators[1:]):
        inner_h = bottom - top - 1
        inner_w = width - 2
        if inner_h <= 0 or inner_w <= 0:
            continue

        # The panel's zero cells define the shape to place there.
        target = {
            (r - top - 1, c - 1)
            for r in range(top + 1, bottom)
            for c in range(1, width - 1)
            if grid[r][c] != frame
        }

        for color, (shape_h, shape_w, cells) in shapes.items():
            if shape_h > inner_h or shape_w > inner_w:
                continue
            off_r = (inner_h - shape_h) // 2
            off_c = (inner_w - shape_w) // 2
            placed = {(r + off_r, c + off_c) for r, c in cells}
            if placed == target:
                for r, c in target:
                    out[top + 1 + r][1 + c] = color
                break

    return out
